import * as R from 'ramda';
import {
  ArticleViewFragment,
  AuthUser,
  CommentInput,
  CommentsDocument,
  useCreateCommentMutation,
} from '../../generated/graphql';
import { useMessageHandler } from '../../lib/hooks/use-message';
import { commentInputSchema } from '../../lib/validation/schema';
import CustomImage from '../common/CustomImage';
import Form from '../forms/form';
import FormTextarea from '../forms/form-teextarea';
import Submit from '../forms/submit';

export default function CommentForm({
  user: { image, username },
  article,
}: {
  user: AuthUser;
  article: ArticleViewFragment;
}) {
  const { success, handleErrors } = useMessageHandler();

  const [createComment, { loading }] = useCreateCommentMutation({
    update(cache, { data }) {
      if (data) {
        const newComment = data.createComment;
        cache.updateQuery({ query: CommentsDocument, variables: { articleId: article.id } }, (data) => ({
          comments: R.prepend(newComment, data.comments),
        }));
      }
    },
    onCompleted: () => success({ content: 'Succeed adding a comment!', mode: 'toast' }),
    onError: (err) => handleErrors({ err, mode: 'toast' }),
  });

  async function onPostComment(input: CommentInput) {
    await createComment({ variables: { slug: article.slug, input } });
  }
  const init: CommentInput = { body: '' };
  return (
    <Form<CommentInput>
      onSubmit={onPostComment}
      mode='onChange'
      schema={commentInputSchema}
      defaultValues={init}
      alert={false}
    >
      <div className='bg-gray-100 border rounded-t-md shadow-sm'>
        <fieldset className='flex flex-col justify-center mx-auto' aria-live='polite'>
          <FormTextarea<CommentInput> name='body' placeholder='Write a comment...' rows={3} clear />

          <div className='py-2 px-4 '>
            <div className='flex flex-wrap items-center justify-between mx-auto'>
              <CustomImage src={image} alt={username} />
              <Submit className='self-end' strict>
                Post Comment
              </Submit>
            </div>
          </div>
        </fieldset>
      </div>
    </Form>
  );
}

import { NetworkStatus } from '@apollo/client';
import { useCallback, useState } from 'react';
import { ArticleViewFragment, useCommentsQuery } from '../../generated/graphql';
import { COMMENTS_PAGE_SIZE } from '../../lib/constants';
import { useCurrentUser } from '../../lib/hooks/use-current-user';
import { useMessageHandler } from '../../lib/hooks/use-message';
import CustomLink from '../common/CustomLink';
import LoadingSpinner from '../common/LoadingSpinner';
import LoadMore from '../common/LoadMore';
import ArticleComment from './ArticleComment';
import CommentForm from './CommentForm';

export default function CommentSection({ article }: { article: ArticleViewFragment }) {
  const { user, loading: userLoading } = useCurrentUser();
  const { message, error, info } = useMessageHandler();

  const fallbackMessage = 'Could not load comments... ';
  const noArticlesMessage = 'No comments here... yet';
  const { data, fetchMore, networkStatus } = useCommentsQuery({
    variables: { articleId: article.id, offset: 0, limit: COMMENTS_PAGE_SIZE },
    fetchPolicy: 'cache-and-network',
    nextFetchPolicy: 'cache-first',
    notifyOnNetworkStatusChange: true,
    onError: () => error({ content: fallbackMessage, mode: 'toast' }),
    onCompleted: (data) => {
      if (data && data.comments.length === 0) info({ content: noArticlesMessage, mode: 'none' });
    },
  });

  const comments = data?.comments;
  const last = comments && comments.length && comments[data.comments.length - 1].id;
  const loading = networkStatus === NetworkStatus.loading;
  const loadMoreLoading = networkStatus === NetworkStatus.fetchMore;

  const [fetchedSize, setFetchedSize] = useState(COMMENTS_PAGE_SIZE);
  const onLoadMore = useCallback(
    async ({ offset, cursor }: { offset: number; cursor: number }) => {
      const { data } = await fetchMore({
        variables: { articleId: article.id, offset, cursor, limit: COMMENTS_PAGE_SIZE },
      });
      setFetchedSize(data.comments.length);
    },
    [article, fetchMore]
  );
  return (
    <div className='p-4 bg-gray-50 '>
      <div className='container flex flex-col items-center mx-auto'>
        <div className='w-full sm:w-8/12'>
          {!userLoading && (
            <>
              {user ? (
                <CommentForm user={user} article={article} />
              ) : (
                <p>
                  <CustomLink href='/login' mode='primary' underlined>
                    Sign in
                  </CustomLink>{' '}
                  or{' '}
                  <CustomLink href='/register' mode='primary' underlined>
                    sign up
                  </CustomLink>{' '}
                  to add comments on this article.
                </p>
              )}
            </>
          )}
          {loading && <LoadingSpinner />}

          <ul className='mt-4'>
            {data?.comments.map((comment) => (
              <li key={comment.id}>
                <ArticleComment comment={comment} />
              </li>
            ))}
          </ul>
          <LoadMore {...{ last, fetchedSize, onLoadMore, loadMoreLoading }} />
        </div>
      </div>
    </div>
  );
}

import { useEffect } from 'react';
import { ArticleViewFragment, AuthUser, useArticleMetaLazyQuery } from '../../generated/graphql';
import FavoritesButton from '../common/FavoritesButton';
import FollowsButton from '../common/FollowsButton';

interface NonOwnerArticleMetaActionsProps {
  article: ArticleViewFragment; // SSR data
  user?: AuthUser;
}

export default function NonOwnerArticleMetaActions({ article, user }: NonOwnerArticleMetaActionsProps) {
  const { slug, favorited, author } = article;
  const [loadArticleMeta, { data, loading }] = useArticleMetaLazyQuery();
  useEffect(() => {
    const load = async () => {
      if (user) await loadArticleMeta({ variables: { slug } }); // fetch article related data of current user
    };
    load();
  }, [user, slug, loadArticleMeta]);
  return (
    <div className='flex space-x-2'>
      {user && !loading && data && data.article ? (
        <>
          <FollowsButton author={data.article.author} />
          <FavoritesButton article={data.article} text={data.article.favorited ? 'Unfavorite ' : 'Favorite '} />
        </>
      ) : (
        <>
          <FollowsButton author={author} />
          <FavoritesButton article={article} text={favorited ? 'Unfavorite ' : 'Favorite '} />
        </>
      )}
    </div>
  );
}

import { useRouter } from 'next/router';
import { ArticlesDocument, ArticleViewFragment, TagsDocument, useDeleteArticleMutation } from '../../generated/graphql';
import { ARTICLES_PAGE_SIZE } from '../../lib/constants';
import { useCurrentUser } from '../../lib/hooks/use-current-user';
import { useMessageHandler } from '../../lib/hooks/use-message';
import CustomButton from '../common/CustomButton';

export default function OwnerArticleMetaActions({ article }: { article: ArticleViewFragment }) {
  const router = useRouter();
  const { handleErrors } = useMessageHandler();
  const { slug } = article;
  const { user } = useCurrentUser();

  const [deleteArticle, { loading }] = useDeleteArticleMutation({
    refetchQueries: [
      { query: TagsDocument },
      { query: ArticlesDocument, variables: { offset: 0, limit: ARTICLES_PAGE_SIZE } },
      { query: ArticlesDocument, variables: { author: user?.username, offset: 0, limit: ARTICLES_PAGE_SIZE } },
    ],
    onCompleted: () => router.replace('/'),
    onError: (err) => handleErrors({ err, mode: 'toast' }),
  });

  async function onDeleteArticle() {
    await deleteArticle({ variables: { slug } });
  }

  return (
    <div className='flex space-x-2'>
      <CustomButton size='s' color='secondary' outlined onClick={() => router.push(`/editor/${slug}`)}>
        <i className='ion-edit'></i>
        &nbsp; Edit
      </CustomButton>
      <CustomButton size='s' color='danger' outlined disabled={loading} onClick={() => onDeleteArticle()}>
        <i className='ion-trash-a'></i>
        &nbsp; Delete
      </CustomButton>
    </div>
  );
}

