  color,
  size,
  outlined,
  className,
}: Pick<ButtonProps, 'size' | 'color' | 'outlined' | 'className'>) =>
  joinStylesFromArray(
    joinStyles(buttonConfig),
    size && buttonSizeConfig[size],
    color && (outlined ? joinStyles(buttonColorConfig[color].outline) : joinStyles(buttonColorConfig[color].default)),
    className
  );

