  return (
    <div className={`${imageConfig.basic} ${imageConfig.size[size]} ${rounded && imageConfig.rounded} ${className}`}>
      <Image
        unoptimized
        src={src || DEFAULT_AVATAR}
        alt={alt}
        layout='fill'
        objectFit='cover'
        placeholder='blur'
        blurDataURL={DEFAULT_AVATAR_PLACEHOLDER}
        onError={onHandleBrokenImage()}
      />
    </div>
  );
}

