  },
  secondary: {
    basic: 'text-gray-500',
    hover: 'hover:text-gray-600',
  },
  reverse: {
    basic: 'text-gray-100',
    hover: 'hover:text-white',
  },
};

const joinLinkStyles = (
  { mode, underlined, className }: Pick<CustomLinkProps, 'mode' | 'underlined' | 'className'>,
  active: boolean
) =>
  joinStylesFromArray(
    linkConfig.basic,
    mode && linkTypeConfig[mode].basic,
    mode && linkTypeConfig[mode].hover,
    active && mode && linkTypeConfig[mode].active,
    underlined && linkConfig.underline,
    className
  );

export default function CustomLink({
  href,
  className,
  underlined = false,
  mode = 'none',
  children,
  ...props
}: CustomLinkProps) {
  const { asPath } = useRouter();
  const active = decodeURIComponent(asPath) === decodeURIComponent(href as string);
  return (
    <Link href={href} {...props}>
      <a className={joinLinkStyles({ mode, underlined, className }, active)}>{children}</a>
    </Link>
  );
}

export default function ErrorMessage({ message }: { message: string }) {
  return <div className='error-msg'>{message}</div>;
}

export type GenericErrors = Record<string, string[]> | string[] | string;

export default function Errors({ errors }: { errors: GenericErrors }) {
  return (
    <ul className='error-messages' style={{ listStyleType: 'none' }}>
      {Array.isArray(errors) ? (
        <li key={errors[0]}>{errors[0]}</li>
      ) : typeof errors === 'string' ? (
        <li key={errors}>{errors}</li>
      ) : (
        Object.entries(errors).map(([field, fieldErrors]) =>
          fieldErrors.map((fieldError) => (
            <li key={field + String(fieldError)}>
              {field} {fieldError}
            </li>
          ))
        )
      )}
    </ul>
  );
}

import { useRouter } from 'next/router';
import {
  ArticleMetaViewFragment,
  ArticlePreviewFragment,
  ArticlesDocument,
  ArticleViewFragment,
  useFavoriteMutation,
  useUnfavoriteMutation,
} from '../../generated/graphql';
import { ARTICLES_PAGE_SIZE } from '../../lib/constants';
import { useCurrentUser } from '../../lib/hooks/use-current-user';
import { useMessageHandler } from '../../lib/hooks/use-message';
import CustomButton from './CustomButton';

interface FavoritesButtonProps {
  article: ArticlePreviewFragment | ArticleViewFragment | ArticleMetaViewFragment;
  className?: string;
  text?: string;
}

export default function FavoritesButton({ article, className, text }: FavoritesButtonProps) {
  const { user } = useCurrentUser();
  const router = useRouter();
  const { handleErrors } = useMessageHandler();
  const { id, slug, favorited, favoritesCount } = article;

  const [favorite, { loading: favoriteLoading }] = useFavoriteMutation({
    refetchQueries: [
      { query: ArticlesDocument, variables: { favorited: user?.username, offset: 0, limit: ARTICLES_PAGE_SIZE } },
    ],
    optimisticResponse: {
      favorite: { id, favorited: true, favoritesCount: favoritesCount + 1, __typename: 'Article' },
    },
    onError: (err) => handleErrors({ err, mode: 'toast' }),
  });
  const [unfavorite, { loading: unfavoriteLoading }] = useUnfavoriteMutation({
    refetchQueries: [
      { query: ArticlesDocument, variables: { favorited: user?.username, offset: 0, limit: ARTICLES_PAGE_SIZE } },
    ],
    optimisticResponse: {
      unfavorite: { id, favorited: true, favoritesCount: favoritesCount - 1, __typename: 'Article' },
    },
    onError: (err) => handleErrors({ err, mode: 'toast' }),
  });
  async function onFavoriteToggle() {
    if (!user) {
      router.push('/login');
      return;
    }
    favorited ? await unfavorite({ variables: { slug } }) : await favorite({ variables: { slug } });
  }

  return (
    <CustomButton
      color='primary'
      size='s'
      outlined={!favorited}
      className={className}
      aria-label='Toggle Favorite'
      disabled={favoriteLoading || unfavoriteLoading}
      onClick={onFavoriteToggle}
    >
      <i className='ion-heart'></i>
      {text ? (
        <>
          &nbsp; {text} <span className='counter'>({favoritesCount})</span>
        </>
      ) : (
        <>&nbsp; {favoritesCount}</>
      )}
    </CustomButton>
  );
}

import { useRouter } from 'next/router';
import { FeedDocument, Profile, useFollowMutation, useUnFollowMutation } from '../../generated/graphql';
import { ARTICLES_PAGE_SIZE } from '../../lib/constants';
import { useCurrentUser } from '../../lib/hooks/use-current-user';
import { useMessageHandler } from '../../lib/hooks/use-message';
import CustomButton from './CustomButton';

interface FollowsButtonProps {
  author: Profile;
  className?: string;
}

export default function FollowsButton({ author, className }: FollowsButtonProps) {
  const { user } = useCurrentUser();
  const router = useRouter();
  const { handleErrors } = useMessageHandler();
  const { following, username } = author;

  const [follow, { loading: followLoading }] = useFollowMutation({
    refetchQueries: [{ query: FeedDocument, variables: { offset: 0, limit: ARTICLES_PAGE_SIZE } }], // reload the first page of user feeds
    optimisticResponse: { follow: { username, following: true, __typename: 'Profile' } },
    onError: (err) => handleErrors({ err, mode: 'toast' }),
  });
  const [unFollow, { loading: unFollowLoading }] = useUnFollowMutation({
    refetchQueries: [{ query: FeedDocument, variables: { offset: 0, limit: ARTICLES_PAGE_SIZE } }],
    optimisticResponse: { unFollow: { username, following: false, __typename: 'Profile' } },
    onError: (err) => handleErrors({ err, mode: 'toast' }),
  });
  async function onFollowToggle() {
    if (!user) {
      router.push('/login');
      return;
    }
    following ? await unFollow({ variables: { username } }) : await follow({ variables: { username } });
  }

  return (
    <CustomButton
      color='secondary'
      size='s'
      outlined={!following}
      className={className}
      onClick={onFollowToggle}
      disabled={followLoading || unFollowLoading}
    >
      {following ? (
        <>
          <i className='ion-minus-round'></i>&nbsp;Unfollow
        </>
      ) : (
        <>
