      />
    </fieldset>
  );
}

export function TextAreaFormGroup({
  type,
  placeholder,
  disabled,
  value,
  rows,
  onChange,
  lg,
}: {
  type: string;
  placeholder: string;
  disabled: boolean;
  rows: number;
  value: string;
  lg: boolean;
  onChange: (ev: React.ChangeEvent<HTMLTextAreaElement>) => void;
}) {
  return (
    <fieldset className='form-group'>
      <textarea
        className={`form-control${!lg ? '' : ' form-control-lg'}`}
        {...{ type, placeholder, disabled, value, onChange, rows }}
        autoComplete='on'
      ></textarea>
    </fieldset>
  );
}

export function ListFormGroup({
  type,
  placeholder,
  disabled,
  value,
  listValue,
  lg,
  onChange,
  onEnter,
  onRemoveItem,
}: {
  type: string;
  placeholder: string;
  disabled: boolean;
  value: string;
  listValue: string[];
  lg: boolean;
  onChange: (ev: React.ChangeEvent<HTMLInputElement>) => void;
  onEnter: () => void;
  onRemoveItem: (index: number) => void;
}) {
  return (
    <fieldset className='form-group'>
      <input
        className={`form-control${!lg ? '' : ' form-control-lg'}`}
        {...{ type, placeholder, disabled, value, onChange }}
        onKeyDown={(ev) => ev.key === 'Enter' && ev.preventDefault()}
        onKeyUp={onListFieldKeyUp(onEnter)}
        autoComplete={`${type === 'password' ? 'off' : 'on'}`}
      />
      <div className='tag-list'>
        {listValue.map((value, index) => (
          <span key={value} className='tag-default tag-pill' onClick={() => onRemoveItem(index)}>
            <i className='ion-close-round'></i>
            {value}
          </span>
        ))}
      </div>
    </fieldset>
  );
}

export function onListFieldKeyUp(onEnter: () => void): (ev: React.KeyboardEvent) => void {
  return (ev) => {
    if (ev.key === 'Enter') {
      ev.preventDefault();
      onEnter();
    }
  };
}

import React, { FC } from 'react';
import { GenericFormField } from '../../lib/utils/genericFormField';
import CustomButton from './CustomButton';
import Errors, { GenericErrors } from './Errors';
import { FormGroup, ListFormGroup, TextAreaFormGroup } from './FormGroup';

export interface GenericFormProps {
  fields: GenericFormField[];
  disabled: boolean;
  formObject: Record<string, string | null>;
  submitButtonText: string;
  errors: GenericErrors;
  onChange: (name: string, value: string) => void;
  onSubmit: (ev: React.FormEvent) => void;
  onAddItemToList?: (name: string) => void;
  onRemoveListItem?: (name: string, index: number) => void;
}

export const GenericForm: FC<GenericFormProps> = ({
  fields,
  disabled,
  formObject,
  submitButtonText,
  errors,
  onChange,
  onSubmit,
  onAddItemToList,
  onRemoveListItem,
}) => (
  <React.Fragment>
    <Errors errors={errors} />

    <form onSubmit={onSubmit}>
      <fieldset>
        {fields.map((field) =>
          field.fieldType === 'input' ? (
            <FormGroup
              key={field.name}
              disabled={disabled}
              type={field.type}
              placeholder={field.placeholder}
              value={formObject[field.name] || ''}
              onChange={onUpdateField(field.name, onChange)}
              lg={field.lg}
            />
          ) : field.fieldType === 'textarea' ? (
            <TextAreaFormGroup
              key={field.name}
              disabled={disabled}
              type={field.type}
              placeholder={field.placeholder}
              value={formObject[field.name] || ''}
              rows={field.rows as number}
              onChange={onUpdateField(field.name, onChange)}
              lg={field.lg}
            />
          ) : (
            <ListFormGroup
              key={field.name}
              disabled={disabled}
              type={field.type}
              placeholder={field.placeholder}
              value={formObject[field.name] || ''}
              onChange={onUpdateField(field.name, onChange)}
              listValue={formObject[field.listName as string] as unknown as string[]}
              onEnter={() => onAddItemToList && field.listName && onAddItemToList(field.listName)}
              onRemoveItem={(index) => onRemoveListItem && field.listName && onRemoveListItem(field.listName, index)}
              lg={field.lg}
            />
          )
        )}
        {/* <button className='btn btn-lg btn-primary pull-xs-right'>{submitButtonText}</button> */}
        <CustomButton color='secondary' size='m'>
          {submitButtonText}
        </CustomButton>
      </fieldset>
    </form>
  </React.Fragment>
);

function onUpdateField(
  name: string,
  onChange: GenericFormProps['onChange']
): (ev: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => void {
  return ({ target: { value } }) => {
    onChange(name, value);
  };
}

