import { ReactNode, useCallback } from 'react';
import { useCountdown, useEventListener } from 'usehooks-ts';
import { ARTICLES_FETCH_MORE_INTERVAL, ARTICLES_PAGE_SIZE } from '../../lib/constants';
import CustomButton from './CustomButton';
import LoadingSpinner from './LoadingSpinner';
import { BaseLoadMoreProps } from './LoadMore';

type ReverseLoadMoreProps = {
  topFetchedSize: number;
  bottomFetchedSize: number;
  topLoading: boolean;
  bottomLoading: boolean;
  children?: ReactNode;
} & BaseLoadMoreProps;

export default function ReverseLoadMore({
  first,
  last,
  onLoadMore,
  loadMoreLoading,
  children,
  topFetchedSize,
  bottomFetchedSize,
  topLoading,
  bottomLoading,
}: ReverseLoadMoreProps) {
  const bottomNoMore = bottomFetchedSize < ARTICLES_PAGE_SIZE;
  const topNoMore = topFetchedSize < ARTICLES_PAGE_SIZE;
  const [count, { startCountdown, resetCountdown }] = useCountdown({ countStart: ARTICLES_FETCH_MORE_INTERVAL });

  const handleScrollToBottom = useCallback(() => {
    if (last && !bottomNoMore && window.scrollY + window.innerHeight >= document.documentElement.scrollHeight) {
      onLoadMore({ offset: 1, cursor: last });
    }
  }, [onLoadMore, last, bottomNoMore]);

  const handleScrollToTop = useCallback(() => {
    if (topNoMore) startCountdown();
    if (first && window.scrollY === 0 && (!topNoMore || count === 0)) {
      onLoadMore({ offset: -1, cursor: first }); // load more and prepend to the list top
      resetCountdown();
      startCountdown();
    }
  }, [onLoadMore, first, topNoMore, count, startCountdown, resetCountdown]);

  useEventListener('scroll', handleScrollToBottom);
  useEventListener('scroll', handleScrollToTop);

  return (
    <div className=' flex flex-col justify-between relative'>
      {loadMoreLoading && topLoading && <LoadingSpinner nowrap overlay />}
      {children}
      {loadMoreLoading && bottomLoading && !bottomNoMore && <LoadingSpinner nowrap />}
      <nav className='flex mt-4'>
        {bottomNoMore && (
          <CustomButton color='secondary' outlined size='s' disabled>
            No More
          </CustomButton>
        )}
      </nav>
    </div>
  );
}

import { animated, useSpring } from '@react-spring/web';
import { useEffect, useRef } from 'react';
import { MessageType, useMessageHandler } from '../../lib/hooks/use-message';
import { joinStylesFromArray } from '../../lib/utils/styles-builder';

const toastConfig = 'fixed right-5 bottom-5 p-4 w-full max-w-xs rounded-lg shadow-lg font-medium whitespace-nowrap';
const toastTypeConfig: { [key in MessageType]: string } = {
  error: 'text-red-600 bg-red-200',
  info: 'text-blue-600 bg-blue-200',
  success: 'text-green-600 bg-green-200',
};

const joinToastStyles = (type: MessageType) => joinStylesFromArray(toastConfig, toastTypeConfig[type]);

export default function Toast() {
  const { message, dismiss } = useMessageHandler();
  const removeRef = useRef(dismiss);
  removeRef.current = dismiss;
  const styles = useSpring({
    // I wonder if there is a way to deal with this fade-in using pure tailwind css
    to: { opacity: message ? 1 : 0 },
    from: { opacity: 0 },
    config: { duration: 300 },
  });
  useEffect(() => {
    if (message?.mode === 'toast') {
      const duration = 3500;
      const id = setTimeout(() => removeRef.current(), duration);

      return () => clearTimeout(id);
    }
  }, [message]);

  return (
    <animated.div style={styles}>
      <>
        {message && message.mode === 'toast' && (
          <div className={joinToastStyles(message.type)} role='alert'>
            <p className='overflow-hidden pr-4'>{message.content}</p>
          </div>
        )}
      </>
    </animated.div>
  );
}

