import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import jwkToPem from 'jwk-to-pem';
import slug from 'slug';
import { PUBLIC_JWK, TOKEN_ALG, TOKEN_KID, TOKEN_PREFIX, TOKEN_TTL } from '../constants';
import { AuthPayload } from './types/user.type';

export default class Utility {
  /**
   *  slugify an article's title using slug and a random suffix
   * @param title
   * @returns
   */
  static slugify = (title: string): string => {
    return `${slug(title, { lower: true })}-${((Math.random() * Math.pow(36, 6)) | 0).toString(36)}`;
  };

  static encodePassword = (password: string): string => {
    return bcrypt.hashSync(password, bcrypt.genSaltSync(10));
  };

  static checkPassword = (password: string, hash: string): boolean => {
    return bcrypt.compareSync(password, hash);
  };

  static issueToken(payload: object) {
    const privateKey = JSON.parse(process.env.PRIVATE_JWK as string);
    return jwt.sign(payload, jwkToPem(privateKey, { private: true }), {
      algorithm: TOKEN_ALG,
      expiresIn: TOKEN_TTL,
      keyid: TOKEN_KID,
    });
  }

  static verifyToken<T>(token: string): T {
    const payload = jwt.verify(token, jwkToPem(PUBLIC_JWK), { algorithms: [TOKEN_ALG] });
    return payload as T;
  }

  static loadCurrentUser(authorization: string | undefined) {
    if (!authorization || !authorization.startsWith(TOKEN_PREFIX)) return;

    const token = authorization.split(TOKEN_PREFIX)[1];
    const payload = this.verifyToken<AuthPayload>(token);
    return payload.sub;
  }

  static wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
}

import { useEffect } from 'react';
import LoadingSpinner from '../../components/common/LoadingSpinner';
import { useCurrentUser } from '../hooks/use-current-user';
import { useReplace } from '../hooks/use-router-methods';

export default function guestOnly(Component: any) {
  const GuestComponent = () => {
    const replace = useReplace();
    const { user, loading } = useCurrentUser();
    useEffect(() => {
      if (!loading && user) replace('/');
    }, [user, loading, replace]);
    if (loading) return <LoadingSpinner />;
    return !user ? <Component /> : <LoadingSpinner />;
  };
  return GuestComponent;
}

import { useEffect } from 'react';
import LoadingSpinner from '../../components/common/LoadingSpinner';
import { useCurrentUser } from '../hooks/use-current-user';
import { usePush } from '../hooks/use-router-methods';

export default function withAuth(Component: any) {
  const AuthenticatedComponent = () => {
    const push = usePush();
    const { user, loading } = useCurrentUser();
    useEffect(() => {
      if (!loading && !user) push('/login');
    }, [user, loading, push]);
    return user ? <Component {...{ user }} /> : <LoadingSpinner />;
  };
  return AuthenticatedComponent;
}

import { FieldMergeFunction, InMemoryCache } from '@apollo/client';
import * as R from 'ramda';

const merge: FieldMergeFunction = (existing: any[], incoming: any[], { args, readField }) => {
  const offset = args?.offset as number;
  const merged = existing ? existing.slice(0) : [];
  const existingIdSet = new Set(merged.map((article) => readField('id', article)));
  incoming = incoming.filter((article) => !existingIdSet.has(readField('id', article)));
  return offset > 0 ? R.concat(merged, incoming) : R.concat(incoming, merged);
};

export const cache = new InMemoryCache({
  typePolicies: {
    Article: {
      keyFields: ['id'],
    },
    Comment: {
      keyFields: ['id'],
    },
    Profile: {
      keyFields: ['username'],
    },
    AuthUser: {
      keyFields: ['id'],
    },
    Tag: {
      keyFields: ['name'],
    },
    Query: {
      fields: {
        feed: {
          keyArgs: [],
          merge,
        },
        articles: {
          keyArgs: ['author', 'favorited', 'tag'],
          merge,
        },
        comments: {
          keyArgs: ['articleId'],
          merge,
        },
      },
    },
  },
});

import { ApolloClient, ApolloLink, createHttpLink } from '@apollo/client';
