import { ApolloClient, ApolloLink, ApolloProvider } from '@apollo/client';
import { setContext } from '@apollo/client/link/context';
import React, { useMemo, useRef } from 'react';
import { cache } from '../cache';
import { cacheLink, errorLink, httpLink } from '../client/apollo-client';
import { useToken } from './use-token';

export function CustomApolloProvider({ children }: { children: React.ReactNode }) {
  const { token } = useToken();
  const tokenRef = useRef<string>();

  // Whenever the token changes, the component re-renders, thus updating the ref.
  tokenRef.current = token;

  // Ensure that the client is only created once.
  const client = useMemo(() => {
    const authLink = setContext((_, { headers }) => ({
      headers: {
        ...headers,
        authorization: tokenRef.current ? `Bearer ${tokenRef.current}` : '',
      },
    }));

    return new ApolloClient({
      link: ApolloLink.from([errorLink, authLink, cacheLink, httpLink]),
      connectToDevTools: process.env.NODE_ENV === 'development',
      cache,
    });
  }, []);

  return <ApolloProvider client={client}>{children}</ApolloProvider>;
}

import { useEffect, useState } from 'react';
import { useCurrentUserLazyQuery } from '../../generated/graphql';
import { useMessageHandler } from './use-message';
import { useToken } from './use-token';

export function useCurrentUser() {
  const { token } = useToken();
  const { handleErrors } = useMessageHandler();
  const [loading, setLoading] = useState<boolean>(true);
  const [loadCurrentUser, { data }] = useCurrentUserLazyQuery({
    fetchPolicy: 'cache-first',
    nextFetchPolicy: 'cache-only',
    onError: (err) => handleErrors({ err, mode: 'none' }),
  });
  useEffect(() => {
    const loadData = async () => {
      if (token) await loadCurrentUser();
      setLoading(false);
    };
    loadData();
  }, [loadCurrentUser, token]);

  return { user: data?.currentUser, loading };
}

import { useEffect } from 'react';
import { useController, useFormContext, useFormState, useWatch } from 'react-hook-form';
import { FormInputBaseProps } from '../../components/forms/FormInput';
import { useMessageHandler } from './use-message';
/**
 * just a few shared uses of <input/> and <textarea/>
 * make sure this hook is inside a react-hook-form context
 * @param
 */
export function useFormCallback<TFormValues>({ name, watch = false, clear = false }: FormInputBaseProps<TFormValues>) {
  const { control, trigger, resetField } = useFormContext();
  const { isSubmitSuccessful } = useFormState();
  const { dismiss, message } = useMessageHandler();
  const { fieldState } = useController({ name, control });
  const { isDirty, isTouched } = fieldState;

  const watching = useWatch({ control, name });
  useEffect(() => {
    if (watch) trigger(name); // trigger validation on change manually
    if (isDirty || isTouched) dismiss(); // dismiss messages from fetching data
  }, [watching, trigger, name, watch, dismiss, isDirty, isTouched]);

  useEffect(() => {
    if (clear && isSubmitSuccessful && (!message || message.type === 'success')) resetField(name); // manually reset field after a successful submit
  }, [clear, isSubmitSuccessful, resetField, name, message]);
}

import { ApolloError, useApolloClient } from '@apollo/client';
import { useRouter } from 'next/router';
import { createContext, useCallback, useContext, useEffect, useState } from 'react';
import { usePush } from './use-router-methods';
import { useToken } from './use-token';

export type MessageType = 'error' | 'info' | 'success';
export type NotifyType = 'alert' | 'toast' | 'none';
export interface Message {
  content: string;
  type: MessageType;
  mode: NotifyType;
}

enum ServerErrorCode {
  Unauthorized = 'UNAUTHENTICATED',
  BadUserInput = 'BAD_USER_INPUT',
  InternalServerError = 'INTERNAL_SERVER_ERROR',
}

interface MessageContext {
  message: Message | null;
  handleErrors: ({ err, mode }: { err: ApolloError; mode: NotifyType }) => void;
  dismiss: () => void;
  dismissing: boolean;
  success: (message: Pick<Message, 'content' | 'mode'>) => void;
  error: (message: Pick<Message, 'content' | 'mode'>) => void;
  info: (message: Pick<Message, 'content' | 'mode'>) => void;
}

const initMessageContext: MessageContext = {
  message: null,
  handleErrors: () => {},
  dismiss: () => {},
  dismissing: false,
  success: () => {},
  error: () => {},
  info: () => {},
};

const messageContext = createContext<MessageContext>(initMessageContext);

export function MessageProvider({ children }: { children: React.ReactNode }) {
  const messageHandler = useProvideMessageHandler();
  return <messageContext.Provider value={messageHandler}>{children}</messageContext.Provider>;
}

export const useMessageHandler = () => {
  return useContext(messageContext);
};

function useProvideMessageHandler() {
  const [message, setMessage] = useState<Message | null>(null);
  const { token, handleChangeToken } = useToken();
  const client = useApolloClient();
  const push = usePush();
  const { asPath } = useRouter();
  const [dismissing, setDismissing] = useState<boolean>(false);

  useEffect(() => {
    const onMount = () => {
      setDismissing(true);
      setMessage(null); // dismiss when path changed
      setDismissing(false);
    };
    onMount();
    return () => setDismissing(false);
  }, [asPath]);

  const success = useCallback(({ content, mode }: Pick<Message, 'content' | 'mode'>) => {
    setMessage({ content, mode, type: 'success' });
  }, []);

  const error = useCallback(({ content, mode }: Pick<Message, 'content' | 'mode'>) => {
    setMessage({ content, mode, type: 'error' });
  }, []);

  const info = useCallback(({ content, mode }: Pick<Message, 'content' | 'mode'>) => {
    setMessage({ content, mode, type: 'info' });
  }, []);

  const dismiss = useCallback(() => {
    setMessage(null);
  }, []);

  const handleErrors = useCallback(
    ({ err: { graphQLErrors, networkError }, mode }: { err: ApolloError; mode: NotifyType }) => {
      const reset = async () => {
        handleChangeToken('');
        await client.resetStore();
        push('/login');
      };

      if (graphQLErrors) {
        for (let err of graphQLErrors) {
          switch (err.extensions.code) {
            case ServerErrorCode.Unauthorized:
              if (token) reset(); // invalid token push to login
              break;
            default:
              setMessage({ content: err.message, mode, type: 'error' });
              break;
          }
        }
        if (networkError) setMessage({ content: networkError.message, mode, type: 'error' });
      }
    },
    [token, handleChangeToken, push, client]
  );
  return { message, handleErrors, dismiss, dismissing, success, info, error };
}

import { useEffect, useRef } from 'react';

export function usePrevious<T>(value: T) {
  // The ref object is a generic container whose current property is mutable ...
  // ... and can hold any value, similar to an instance property on a class
  const ref = useRef<T>();
  // Store current value in ref
  useEffect(() => {
    ref.current = value;
  }, [value]); // Only re-run if value changes
  // Return previous value (happens before update in useEffect above)
  return ref.current;
}

import type { NextRouter } from 'next/router';
import { useRouter } from 'next/router';
import { useRef, useState } from 'react';

export function usePush(): NextRouter['push'] {
  const router = useRouter();
  const routerRef = useRef(router);

  routerRef.current = router;

  const [{ push }] = useState<Pick<NextRouter, 'push'>>({
    push: (path) => routerRef.current.push(path),
  });
  return push;
}

export function useReplace(): NextRouter['replace'] {
  const router = useRouter();
  const routerRef = useRef(router);

  routerRef.current = router;

  const [{ replace }] = useState<Pick<NextRouter, 'replace'>>({
    replace: (path) => routerRef.current.replace(path),
  });
  return replace;
}

import React, { createContext, useCallback, useContext } from 'react';
import { useLocalStorage } from 'usehooks-ts';

interface TokenContext {
  token: string;
  handleChangeToken: (token: string) => void;
}

const initTokenContext: TokenContext = {
  token: '',
  handleChangeToken: (token: string) => {},
};

const tokenContext = createContext<TokenContext>(initTokenContext);

export function TokenProvider({ children }: { children: React.ReactNode }) {
  const tokenHandler = useProvideToken();
  return <tokenContext.Provider value={tokenHandler}>{children}</tokenContext.Provider>;
}

export const useToken = () => {
  return useContext(tokenContext);
};

function useProvideToken() {
  const [token, setToken] = useLocalStorage<string>('token', '');
  const handleChangeToken = useCallback(
    (token: string) => {
      setToken(token);
    },
    [setToken]
  );
  return { token, handleChangeToken };
}

import { AnySchema, object } from 'yup';
import { AuthUser, useCheckEmailLazyQuery, useCheckUsernameLazyQuery, UserUpdateInput } from '../../generated/graphql';
import { bio, email, image, password, username } from '../validation/schema';
import { useMessageHandler } from './use-message';

export function useCheckUser(origin?: AuthUser) {
  const { handleErrors } = useMessageHandler();
  const [checkUsername] = useCheckUsernameLazyQuery({
    onError: (err) => handleErrors({ err, mode: 'alert' }),
  });
  const [checkEmail] = useCheckEmailLazyQuery({
    onError: (err) => handleErrors({ err, mode: 'alert' }),
  });

  return object<Record<keyof UserUpdateInput, AnySchema>>({
    username: username.test('check-username', 'Username had been taken', async (value) => {
      if (!value || origin?.username === value) return true;
      const { data } = await checkUsername({ variables: { username: value } });
      return data?.checkUsername === null;
    }),
    email: email.test('check-email', 'Email had been taken', async (value) => {
      if (!value || origin?.email === value) return true;
      const { data } = await checkEmail({
        variables: { email: value },
      });
      return data?.checkEmail === null;
    }),
    password,
    bio,
    image,
  });
}

