import prisma from '../../lib/api/prisma';
import { schema } from '../../lib/api/schema';
import Utility from '../../lib/api/utils';

const cors = Cors();

let apiHandler: RequestHandler;
async function getApiHandler() {
  const server = new ApolloServer({
    schema: schema,
    context: ({ req }): Context => {
      try {
        const id = Utility.loadCurrentUser(req.headers.authorization);
        return { prisma, currentUser: id ? { id } : undefined };
      } catch {
        // should be a token parsing error, treat as a guest
        return { prisma };
      }
    },
    csrfPrevention: true,
    introspection: process.env.NODE_ENV === 'development',
    cache: 'bounded',
    plugins: R.concat(
      [ApolloServerPluginCacheControl({ defaultMaxAge: 5 })],
      process.env.NODE_ENV === 'development' ? [] : [ApolloServerPluginLandingPageDisabled()]
    ),
    persistedQueries: { ttl: 1500 },
    formatError: (err) => {
      if (
        err.message === 'Not authorized' // nexus authorize plugin error message
      ) {
        return new AuthenticationError('unauthorized', {
          path: err.path,
          locations: err.locations,
        });
      } else if (err.message.includes('prisma') || err.message.includes('database')) {
        return new ApolloError('Internal server error', 'INTERNAL_SERVER_ERROR', {
          path: err.path,
          locations: err.locations,
        });
      }
      return err;
    },
  });

  if (!apiHandler) {
    await server.start();
    apiHandler = server.createHandler({
      path: '/api',
    });
  }
  return apiHandler;
}

export default cors(async (req, res) => {
  const apiHandler = await getApiHandler();
  if (req.method === 'OPTIONS') {
    res.end();
    return false;
  }
  return apiHandler(req, res);
});

export const config = {
  api: {
    bodyParser: false,
  },
};

import { GetServerSideProps } from 'next';
import ArticleJsonMeta from '../../components/article/article-json-meta';
import ArticleMeta from '../../components/article/ArticleMeta';
import ArticlePageBanner from '../../components/article/ArticlePageBanner';
import CommentSection from '../../components/article/CommentSection';
import Marked from '../../components/article/marked';
import TagList from '../../components/common/TagList';
import Wrapper from '../../components/common/wrapper';
import { ArticleDocument, ArticleQuery, ArticleViewFragment } from '../../generated/graphql';
import client from '../../lib/client/apollo-client';
import { BASE_URL } from '../../lib/constants';
import Custom404 from '../404';

const ArticlePage = ({ article }: { article: ArticleViewFragment }) => {
  if (!article) return <Custom404 />;
  const { slug, title, description } = article;
  return (
    <Wrapper
      {...{ title, description }}
      openGraph={{
        url: `${BASE_URL}/article/${slug}`,
        title,
        description,
      }}
    >
      <ArticleJsonMeta article={article} />
      <ArticlePageBanner article={article} />

      <div className='container flex flex-wrap flex-col mx-auto mt-8'>
        <div className='w-full'>
          <Marked content={article.body} className='mb-4' />
        </div>
        <TagList outlined tagList={article.tagList} />

        <hr className='my-4' />

        <div className='mt-16 self-center'>
          <ArticleMeta article={article} />
        </div>
      </div>
      <CommentSection article={article} />
    </Wrapper>
  );
};

export default ArticlePage;

export const getServerSideProps: GetServerSideProps = async (context) => {
  const { slug } = context.query;
  const { data } = await client.query<ArticleQuery>({
    query: ArticleDocument,
    variables: { slug },
    errorPolicy: 'ignore',
  });
  return {
    props: { article: data.article },
  };
};

import { useRouter } from 'next/router';
import LoadingSpinner from '../../components/common/LoadingSpinner';
import Wrapper from '../../components/common/wrapper';
import ArticleEditor from '../../components/editor/ArticleEditor';
import { AuthUser, useEditArticleQuery } from '../../generated/graphql';
import withAuth from '../../lib/auth/with-auth';
import Custom404 from '../404';

const EditArticle = ({ user }: { user: AuthUser }) => {
  const { slug } = useRouter().query as { slug: string };
  const { data, loading } = useEditArticleQuery({ variables: { slug } });
  if (loading || !data) return <LoadingSpinner />;
  const { article } = data;
  if (
    !article ||
    // owner check
    article.author.username !== user.username
  )
    return <Custom404 />;

  return (
    <Wrapper title='Edit article'>
      <ArticleEditor {...{ user, article }} />
    </Wrapper>
  );
};

export default withAuth(EditArticle);

