import type { NextPage } from 'next';
import { useRouter } from 'next/router';
import * as R from 'ramda';
import { useEffect, useState } from 'react';
import ArticlesViewer from '../components/article-list/ArticlesViewer';
import { TabProps } from '../components/common/Tab';
import Wrapper from '../components/common/wrapper';
import HomeBanner from '../components/home/Banner';
import HomeSidebar from '../components/home/Sidebar';
import { ArticlesQueryVariables } from '../generated/graphql';
import { useCurrentUser } from '../lib/hooks/use-current-user';

const Home: NextPage = () => {
  const router = useRouter();
  const { feed, tag } = useRouter().query as { feed?: string; tag?: string };
  const [tabs, setTabs] = useState<TabProps[]>([]);
  const { user, loading } = useCurrentUser();
  const [isFeedQuery, setFeedQuery] = useState<boolean>(false);
  const [queryFilter, setQueryFilter] = useState<ArticlesQueryVariables>({});
  useEffect(() => {
    if (router.isReady && !loading) {
      setFeedQuery(!!user && !!feed);
      setQueryFilter(tag ? { tag } : {});
      setTabs(
        R.unnest([
          user ? [{ name: 'Your Feed', href: '/?feed=true' }] : [],
          [{ name: 'Global Feed', href: '/' }],
          tag ? [{ name: `# ${tag}`, href: `/?tag=${tag}` }] : [],
        ])
      );
    }
  }, [feed, tag, user, router.isReady, loading]);

  return (
    <Wrapper title='Home'>
      <HomeBanner />
      <div className='container flex flex-col-reverse justify-center mt-8 mx-auto md:flex-row'>
        <main className='basis-9/12 shrink-0'>
          <ArticlesViewer {...{ tabs, queryFilter, isFeedQuery }} />
        </main>
        <aside className='w-full sticky self-start md:top-16 md:ml-8'>
          <HomeSidebar />
        </aside>
      </div>
    </Wrapper>
  );
};

export default Home;

import { useApolloClient } from '@apollo/client';
import { NextPage } from 'next';
import { useRouter } from 'next/router';
import CustomLink from '../components/common/CustomLink';
import Wrapper from '../components/common/wrapper';
import Form from '../components/forms/form';
import FormInput from '../components/forms/FormInput';
import Submit from '../components/forms/submit';
import { useLoginMutation, UserLoginInput } from '../generated/graphql';
import guestOnly from '../lib/auth/guest-only';
import { useMessageHandler } from '../lib/hooks/use-message';
import { useToken } from '../lib/hooks/use-token';
import { loginInputSchema } from '../lib/validation/schema';

const Login: NextPage = () => {
  const router = useRouter();
  const client = useApolloClient();
  const { handleChangeToken } = useToken();
  const { handleErrors } = useMessageHandler();

  const [login, { loading }] = useLoginMutation({
    onCompleted: async (data) => {
      if (data) {
        handleChangeToken(data.login.token as string);
        await client.resetStore();
        router.replace('/');
      }
    },
    onError: (err) => handleErrors({ err, mode: 'alert' }),
  });

  async function onLogin(input: UserLoginInput) {
    await login({ variables: { input } });
  }
  const init = { email: '', password: '' };
  return (
    <Wrapper title='Sign in'>
      <div className='container flex flex-wrap flex-col items-center mx-auto pt-12'>
        <h1 className='text-4xl font-extralight'>Sign in</h1>
        <p className='mt-4'>
          <CustomLink href='/register' mode='primary' underlined>
            Need an account?
          </CustomLink>
        </p>
        <div className='w-full sm:w-10/12 md:w-8/12 lg:w-6/12'>
          <Form<UserLoginInput> onSubmit={onLogin} schema={loginInputSchema} defaultValues={init}>
            <fieldset className='flex flex-col justify-center mx-auto' aria-live='polite'>
              <FormInput<UserLoginInput> name='email' placeholder='Email' />
              <FormInput<UserLoginInput> name='password' placeholder='Password' type='password' />

              <Submit size='l' className='self-end'>
                Sign in
              </Submit>
            </fieldset>
          </Form>
        </div>
      </div>
    </Wrapper>
  );
};

export default guestOnly(Login);

import { NextPage } from 'next';
import { useRouter } from 'next/router';
import { useEffect, useState } from 'react';
import ArticlesViewer from '../../components/article-list/ArticlesViewer';
import LoadingSpinner from '../../components/common/LoadingSpinner';
import { TabProps } from '../../components/common/Tab';
import Wrapper from '../../components/common/wrapper';
import UserInfo from '../../components/profile/UserInfo';
import { ArticlesQueryVariables, useProfileLazyQuery } from '../../generated/graphql';
import Custom404 from '../404';

const Profile: NextPage = () => {
  const router = useRouter();
  const { username, favorites } = useRouter().query as { username: string; favorites?: string };
  const [queryFilter, setQueryFilter] = useState<ArticlesQueryVariables>({});
  const [tabs, setTabs] = useState<TabProps[]>([]);
  const [loadProfile, { data, loading }] = useProfileLazyQuery();
  useEffect(() => {
    if (router.isReady) {
      loadProfile({ variables: { username } });
      setQueryFilter(favorites ? { favorited: username } : { author: username });
      setTabs([
        { name: 'My Articles', href: `/profile/${username}` },
        { name: 'Favorited Articles', href: `/profile/${username}?favorites=true` },
      ]);
    }
  }, [username, favorites, router.isReady, loadProfile]);

  if (loading || !data) return <LoadingSpinner />;
  const { profile } = data;
  if (!profile) return <Custom404 />;
  return (
    <Wrapper title='Profile'>
      <UserInfo author={profile} />
      <div className='container flex flex-wrap justify-center mx-auto mt-8'>
        <div className='w-full'>
          <ArticlesViewer {...{ tabs, queryFilter }} />
        </div>
      </div>
    </Wrapper>
  );
};

export default Profile;

